import{esc,button,input,select}from'../phase4/ui.js';
import{MODES,familyNumbers,currentTen,unitState}from'./b10-model.js';
const f=(key,label,value)=>input(key,label,value,'autocomplete="off" spellcheck="false"');
const dots=(n,color='a',cross=0)=>`<div class="b10-dots">${Array.from({length:n},(_,i)=>`<i class="${color} ${i<cross?'cross':''}"></i>`).join('')||'<span class="b10-zero">空着</span>'}</div>`;
function hands(n,c){return`<svg class="b10-hand ${c}" viewBox="0 0 180 130" role="img" aria-label="${n}根手指示意"><path d="M18 72H156V107Q156 123 136 123H39Q18 123 18 107Z"/><g>${Array.from({length:5},(_,i)=>`<rect x="${20+i*28}" y="${[43,15,4,20,47][i]}" width="23" height="${90-[43,15,4,20,47][i]}" rx="11" class="${i<n?'up':'down'}"/>`).join('')}</g></svg>`;}
const objects=(t,n,c='a',cross=0)=>t.rep==='fingers'?hands(n,c):`<div class="${t.rep==='frame'?'b10-framebox':''}">${dots(n,c,cross)}</div>`;
const modeNames={'add':'先合左边和右边','swap':'交换位置再合起来','take-a':'从整体拿走左边那部分','take-b':'从整体拿走右边那部分'};
const record=s=>`<div class="b10-records">${s.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;
const counter=(group,label,n,action='story-counter',attr='group')=>`<div class="b10-counter"><span>${label}</span>${button(action,'−',`data-${attr}="${group}" data-delta="-1" aria-label="${label}少一个" ${n===0?'disabled':''}`)}<strong>${n}</strong>${button(action,'＋',`data-${attr}="${group}" data-delta="1" aria-label="${label}多一个"`)}</div>`;
export function visual(t,m){switch(t.type){
 case'x-joinstory':{const d=m.done;let body=`<div class="b10-trays"><section><p>${t.compare?'红珠这一排':'原来的一堆'}</p>${objects(t,m.left)}</section><section><p>${t.compare?'蓝珠这一排':'另一部分 / 要拿走的'}</p>${objects(t,m.right,'b')}</section></div>`;
 if(d){const a=m.swapped?d.b:d.a,b=m.swapped?d.a:d.b;body=`<p class="b10-caption">${m.swapped?'两部分换了位置':'你刚才做的动作'} · ${a} ${d.op==='+'?'合上':'拿走'} ${b}</p>`+(t.compare?`<div class="b10-compare"><div>${dots(a,'a',b)}</div><div>${dots(b,'b',Math.min(a,b))}</div><p>同列配成一对；没有配到的，表示相差的部分。</p></div>`:d.op==='+'?`<div class="b10-merged">${objects(t,a,m.swapped?'b':'a')}${objects(t,b,m.swapped?'a':'b')}</div>`:`<div class="b10-merged">${objects(t,a,'a',Math.min(a,b))}</div>${b>a?'<p class="b10-caption">这堆已经拿空，仍然不够。这个实物模型不能完成这次取走。</p>':''}`);}
 if(t.balance)body+=`<section class="b10-reference"><p>另一边：${t.balance.join(' 与 ')}</p><div class="b10-merged">${dots(t.balance[0])}${dots(t.balance[1],'b')}</div></section>`;
 return body+(m.first!==null?`<p class="muted">最初猜的是 ${esc(m.first)}；改主意也没关系。</p>`:'');}
 case'x-splitbench':{const tray=left=>`<section><p>${left?'左边':'右边'}</p><div class="b10-tokens">${Array.from({length:t.total},(_,i)=>i).filter(i=>m.left.includes(i)===left).map(i=>button('split-token','',`data-index="${i}" class="b10-token ${left?'a':'b'}" aria-label="把第${i+1}颗移到${left?'右':'左'}边"`)).join('')||'<span>空着也是一种分法</span>'}</div></section>`;return`<p class="b10-caption">共 ${t.total} 颗 · 点一颗，就搬到另一边</p><div class="b10-trays">${tray(true)}${tray(false)}</div>`+record(m.saved.map(s=>s.eq));}
 case'x-tenbridge':{const token=(i,c,moved)=>button('ten-token','',`data-index="${i}" class="b10-token ${c} ${t.op==='-'&&moved?'cross':''}" aria-label="${t.op==='+'?(moved?'移回':'搬动'):(moved?'放回':'拿走')}第${i+1}颗" ${m.first===null||m.landmark?.ids.includes(i)||(t.op==='-'&&!m.landmark&&i<10)?'disabled':''}`);
 const cells=t.op==='+'?Array.from({length:t.a},()=>'<i class="b10-token a"></i>').join('')+m.moved.map(i=>token(i,'b',true)).join(''):Array.from({length:t.a},(_,i)=>token(i,'a',m.moved.includes(i))).join('');
 return`<p class="b10-caption">${t.a} ${t.op==='+'?'＋':'−'} ${t.b} · ${m.landmark?'十这一站已经留下':'先让十出现'}</p><div class="b10-ten-grid">${cells}${Array.from({length:Math.max(0,20-(t.op==='+'?t.a+m.moved.length:t.a))},()=>'<i class="b10-hole"></i>').join('')}</div>`+(t.op==='+'?`<p>还在后一堆</p><div class="b10-tokens">${Array.from({length:t.b},(_,i)=>i).filter(i=>!m.moved.includes(i)).map(i=>token(i,'b',false)).join('')||'<span>都搬过来了</span>'}</div>`:'')+`<p class="muted">${m.first===null?'先猜，再动手。':`最初猜 ${esc(m.first)}。圆片保留原来的颜色，搬动没有增加新的圆片。`}</p>`;}
 case'x-factfamily':{const mode=m.mode,a=t.a,b=t.b,whole=a+b;return`<p class="b10-caption">同样两部分：${a} 和 ${b} · 整体 ${whole}</p>`+(mode==='take-a'||mode==='take-b'?`<div class="b10-merged">${dots(a,'a',mode==='take-a'?a:0)}${dots(b,'b',mode==='take-b'?b:0)}</div>`:mode==='swap'?`<div class="b10-merged">${dots(b,'b')}${dots(a)}</div>`:`<div class="${mode?'b10-merged':'b10-trays'}">${dots(a)}${dots(b,'b')}</div>`)+`<p>${mode?modeNames[mode]:'选一个动作，让这两个部分动起来。'}</p>`+record(m.saved.map(s=>s.eq));}
 case'x-recallbench':{const c=t.cases[m.cursor];return c?`<p class="b10-caption">${m.cursor+1} / ${t.cases.length}</p><p class="b10-equation">${c.a} ${c.op==='+'?'＋':'−'} ${c.b} = ?</p>`+(m.help.includes(m.cursor)?`<div class="b10-merged">${dots(c.a,'a',c.op==='-'?c.b:0)}${c.op==='+'?dots(c.b,'b'):''}</div><p class="muted">看过圆片也会留下记录；这不是扣分。</p>`:''):'<p class="b10-caption">这几组已经留下了。之后还可以换一天再试。</p>';}
 case'x-countsteps':return`<div class="b10-stations"><span>${esc(m.start)||'起点'}</span>${m.hops.map(n=>`<b>${t.op==='+'?'→':'←'}</b><span>${n}</span>`).join('')}</div><p class="muted">已经走了 ${m.hops.length} 步，起点没有算进去。</p>`;
 case'x-threegroups':{const groups=t.values.map((n,i)=>`<section class="${m.selected.includes(i)?'chosen':''}">${button('triple-pick',`${n} 颗这一堆`,`data-index="${i}" aria-pressed="${m.selected.includes(i)}" ${m.merged?'disabled':''}`)}${dots(n,['a','b','c'][i])}</section>`).join('');return`<div class="b10-three">${groups}</div>`+(m.merged?`<p>先合这两堆：</p><div class="b10-merged">${m.selected.map(i=>dots(t.values[i],['a','b','c'][i])).join('')}</div><p>另外那一堆还要带上。</p>`:'<p>选两堆，再把它们合起来。</p>')+record(m.saved.map(s=>`${t.values[s.pair[0]]} 与 ${t.values[s.pair[1]]} 先合成 ${s.sub}；再带上 ${t.values.find((_,i)=>!s.pair.includes(i))}，一共 ${s.total}`));}
 case'x-unitadd':{const u=unitState(t,m);return`<div class="b10-trays"><section><p>${m.joined?'合起来以后':'原来'}</p><div class="b10-bundles">${Array.from({length:u.tens},()=>'<i>十</i>').join('')}</div>${dots(u.ones)}</section><section><p>${m.joined?'刚才加进来的部分（记录）':'准备增加'}</p><div class="b10-bundles">${Array.from({length:m.tens},()=>'<i>十</i>').join('')}</div>${dots(m.ones,'b')}</section></div><p class="muted">一捆代表十个一。换捆 ${m.exchanges} 次。</p>`;}
 case'x-subgroups':{const p=m.paths[m.branch],a=m.branch===0;return`<div class="b10-actions">${button('subgroups-branch','(10−3)−2',`data-index="0" aria-pressed="${a}"`)}${button('subgroups-branch','10−(3−2)',`data-index="1" aria-pressed="${!a}"`)}</div><p class="b10-equation">${a?'先算10−3，再减2':'先算3−2，再让10减去这份结果'}</p><div class="b10-merged">${dots(p.length===2?p[1]:p.length===0?(a?10:3):a?p[0]:10,'a',p.length===0?(a?3:2):p.length===1?(a?2:p[0]):0)}</div>`+record(m.paths.map((p,i)=>`${i===0?'左':'右'}边：${p.join(' → ')||'还没留下结果'}`));}
}return'';}
export function controls(t,m){switch(t.type){
 case'x-joinstory':return`<div class="b10-actions">${counter('left','原来的一堆',m.left)}${counter('right','另一部分',m.right)}</div>`+f('guess',t.hidden?'先猜藏起来的数量是多少':'先猜最后有多少',m.guess)+select('op','让圆片怎么动',m.op,[['+','合起来'],['-',t.compare?'两排配对，找多出的':'拿走一部分']])+button('story-do',t.compare?'让两排配对':'做这个动作')+(m.done?f('equation',t.balance?'把两边一样多写成算式':'写下刚才的算式',m.equation)+(t.swap?button('story-swap',m.swapped?'换回原来的位置':'把两部分交换位置')+(m.swapped?(t.op==='+'?f('otherEquation','换位置后的算式',m.otherEquation):select('shortage','交换后，实物够不够拿',m.shortage,[['not-enough','拿空也不够，这个实物模型做不到'],['same','和刚才结果相同']])):''):''):'');
 case'x-splitbench':return f('equation','把这次分法写成算式',m.equation)+button('split-save','留下这一种分法');
 case'x-tenbridge':return m.first===null?f('guess','先猜最后有多少',m.guess)+button('ten-predict','留下猜想，再搬圆片'):(m.landmark?button('ten-finish','剩下的也搬好，合在一起看'):button('ten-landmark','把十这一站留下'))+button('ten-reset','重新搬一次')+(m.landmark?f('firstPart','先搬了几个才到十',m.firstPart)+f('secondPart','接着还要搬几个',m.secondPart)+f('equation','整个变化写成算式',m.equation):'');
 case'x-factfamily':return`<div class="b10-actions">${MODES.map(mode=>button('family-mode',modeNames[mode],`data-mode="${mode}" aria-pressed="${mode===m.mode}"`)).join('')}</div>`+(m.mode?f('equation','把这次动作写成算式',m.equation)+button('family-save','留下这句话'):'');
 case'x-recallbench':return m.cursor<t.cases.length?f('answer','这次是多少',m.answer)+button('recall-save','留下，再试下一组')+button('recall-help','看看圆片'):'';
 case'x-countsteps':return f('start','从哪个数出发',m.start)+f('next','下一站是多少',m.next)+button('steps-next','走到这一站')+button('steps-undo','退回上一步')+f('equation','把整个变化写成算式',m.equation);
 case'x-threegroups':return(m.merged?f('sub','先合起来是几颗',m.sub)+f('total','再带上第三堆，总共几颗',m.total)+button('triple-save','留下这种做法'):button('triple-merge','先把选的两堆合起来',m.selected.length!==2?'disabled':''))+button('triple-reset','重新选这两堆');
 case'x-unitadd':return`<div class="b10-actions">${counter('tens','增加几个十',m.tens,'unit-counter','unit')}${counter('ones','增加几个一',m.ones,'unit-counter','unit')}</div>`+button('unit-join','把准备的这一堆加进去')+button('unit-exchange','十个一换成一个十',!m.joined||unitState(t,m).ones<10?'disabled':'')+f('equation','按实际数量写成算式',m.equation);
 case'x-subgroups':return(m.paths[m.branch].length<2?f('next',m.paths[m.branch].length?'第二步的结果':'第一步的结果',m.next)+button('subgroups-next','留下这一步'):'')+button('subgroups-undo','取回最后一步');
}return'';}
export const render=(t,m)=>`<section class="b10-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p role="status" class="b10-issue">${esc(m.issue)}</p>`:''}</div></section>`;
